      T("反正切函数", formula=r"y=\arctan x,\ x\in\mathbb{R},\ y\in(-\frac{\pi}{2},\frac{\pi}{2})", explain="正切函数在(-π/2,π/2)上的反函数。", deriv="限制正切到单调区间后取反函数。", app="求角度、斜率转角度。", note="水平渐近线y=±π/2。", hist="反三角函数。", ext="奇函数，递增，值域开区间。"),
      T("反余切函数", formula=r"y=\operatorname{arccot} x,\ x\in\mathbb{R},\ y\in(0,\pi)", explain="余切函数在(0,π)上的反函数。", deriv="类似反正切。", app="求角度。", note="arctanx+arccotx=π/2。", hist="反三角函数。", ext="递减。"),
      T("反正弦性质", formula=r"\arcsin(-x)=-\arcsin x", explain="反正弦是奇函数。", deriv="由正弦是奇函数推出。", app="化简反三角表达式。", note="sin(arcsinx)=x(x∈[-1,1])。", hist="反三角恒等式。", ext="arcsinx+arccosx=π/2。"),
